// Background task management for the One Village PWA.
//
// The service worker generated by vite-plugin-pwa (Workbox) handles offline caching and the fetch
// lifecycle automatically. This module adds the *Background Sync* capability: when the app goes
// offline and an action can't be sent immediately (e.g. sending a chat message, creating a
// booking), the app can register a one-off sync tag and let the browser retry the queued work when
// connectivity returns — even if the user has closed the tab.
//
// NOTE: registering a sync tag is only useful if the service worker has a matching 'sync' event
// listener that drains the queue. The generated Workbox SW does NOT include one by default, so a
// production build that wants real background drain should switch to `injectManifest` with a custom
// sw.ts that adds:
//
//   self.addEventListener('sync', (event) => {
//     if (event.tag === 'ov-sync') event.waitUntil(drainQueuedRequests());
//   });
//
// Until then this is a safe, forward-compatible best-effort: it registers when supported and no-ops
// otherwise. The in-app queue (QueuedRequest[] below) still retries on the next 'online' event.

interface QueuedRequest {
  url: string;
  method: string;
  body: any;
  queuedAt: number;
}

const QUEUE_KEY = "ov_outbox";
let syncSupported: boolean | null = null;

async function supportsSync(): Promise<boolean> {
  if (syncSupported !== null) return syncSupported;
  try {
    if (!("serviceWorker" in navigator) || !("SyncManager" in window)) {
      syncSupported = false;
      return false;
    }
    const reg = await navigator.serviceWorker.ready;
    syncSupported = !!(reg && (reg as any).sync);
    return syncSupported;
  } catch {
    syncSupported = false;
    return false;
  }
}

/** Registers a one-off background sync so queued work drains when connectivity returns. */
export async function requestBackgroundSync(tag = "ov-sync"): Promise<void> {
  try {
    if (!(await supportsSync())) return;
    const reg = await navigator.serviceWorker.ready;
    await (reg as any).sync.register(tag);
  } catch (err) {
    // Best-effort: some browsers throw if the SW isn't active yet or the tag is invalid.
    // The in-app outbox below still retries on the next 'online' event.
  }
}

/** Queue a failed write to retry later (offline outbox). Returns the new queue length. */
export function enqueue(request: Omit<QueuedRequest, "queuedAt">): number {
  try {
    const q: QueuedRequest[] = JSON.parse(localStorage.getItem(QUEUE_KEY) || "[]");
    q.push({ ...request, queuedAt: Date.now() });
    localStorage.setItem(QUEUE_KEY, JSON.stringify(q.slice(-100))); // cap at 100
    requestBackgroundSync();
    return q.length;
  } catch {
    return 0;
  }
}

/** Drain the offline outbox. Call on 'online' / app resume. Returns number of requests sent. */
export async function flushOutbox(): Promise<number> {
  let sent = 0;
  try {
    const q: QueuedRequest[] = JSON.parse(localStorage.getItem(QUEUE_KEY) || "[]");
    if (!q.length) return 0;
    const remaining: QueuedRequest[] = [];
    for (const item of q) {
      try {
        const res = await fetch(item.url, {
          method: item.method,
          headers: { "Content-Type": "application/json" },
          body: item.body != null ? JSON.stringify(item.body) : undefined,
        });
        if (res.ok) sent++;
        else remaining.push(item);
      } catch {
        remaining.push(item); // still offline; keep for next time
      }
    }
    localStorage.setItem(QUEUE_KEY, JSON.stringify(remaining));
  } catch {
    /* ignore */
  }
  return sent;
}